# Intro of the Adventure and its scenes, in French (the English and the other languages: assets/lang/<code>.json).
# "\n" ends a line, an empty line is a pause; {name} is the pilot's name.
_INTRO_FR = {
    "story_intro_1": (
        "Tout a commencé le 1er juin 2169 par le silence.\n"
        "\n"
        "À 11 h 42, les communications avec la station scientifique avancée TR-01 Huygens, "
        "sur Triton, en orbite de Neptune, ont brutalement cessé.\n"
        "\n"
        "Pas de signal de détresse.\n"
        "Pas d'alerte.\n"
        "\n"
        "La transmission a été coupée en pleine conversation sur la qualité des rations alimentaires…"
    ),
    "story_intro_2": (
        "On ne le savait pas encore, mais c'était la première rencontre de l'humanité "
        "avec une espèce intelligente extraterrestre.\n"
        "\n"
        "91 personnes vivaient sur la station Huygens. 91 hommes et femmes, "
        "morts dans la destruction soudaine de leur habitat…\n"
        "\n"
        "Dans les mois qui ont suivi, toutes les bases humaines des systèmes extérieurs "
        "ont été détruites par ceux que nous allions appeler les Avioïdes. "
        "Des centaines de milliers de morts en quelques semaines. "
        "L'EDF (Earth Defense Force) a été balayée.\n"
        "\n"
        "Pas de langage.\n"
        "Pas de communication.\n"
        "Aucune revendication.\n"
        "\n"
        "Uniquement des attaques, et la destruction méthodique et systématique "
        "de tout ce qui est humain."
    ),
    "story_intro_3": (
        "Sans Mars, les Avioïdes nous auraient balayés et l'humanité n'existerait plus.\n"
        "\n"
        "Mars, avec l'aide de Grok 294.5, la super-intelligence qui dirige la planète, "
        "avait construit un nouveau type de vaisseau de combat : les chasseurs EDF42-Shield, "
        "que tout le monde appelle simplement Shield.\n"
        "\n"
        "Grâce à eux, et à une poignée de pilotes prêts à mourir, "
        "les Avioïdes ont été contenus… un moment.\n"
        "\n"
        "Mais petit à petit, les Shields ont tous été détruits, "
        "les uns après les autres, par des hordes infinies d'ennemis."
    ),
    "story_intro_4": (
        "Aujourd'hui, deux ans après la destruction de la station Huygens, "
        "le dernier Shield a été détruit et je suis le seul pilote de Shield encore en vie.\n"
        "\n"
        "Je me rends sur Phobos, dans une station de recherche où, paraît-il, "
        "il reste un prototype de Shield. C'est celui qui sert au professeur Kamarasov "
        "pour ses recherches sur l'intrication quantique macroscopique.\n"
        "\n"
        "Kamarasov et Grok 294.5 ont équipé l'EDF-Shield-NX01 de leur dispositif fabuleux : "
        "l'ancrage quantique. Quand le Shield-NX01 est détruit, son double quantique "
        "réapparaît à la base, avec son pilote ! Chaque mission rend la suite moins périlleuse.\n"
        "\n"
        "L'espoir renaît. À bord de ce prototype à peine capable de voler, "
        "je peux renverser le cours de l'histoire, moi, {name}, j'en suis maintenant certain."
    ),
    "story_intro_4v": (
        "Aujourd'hui, deux ans après la destruction de la station Huygens, "
        "le dernier Shield a été détruit et je suis le seul pilote de Shield encore en vie.\n"
        "\n"
        "Je me rends sur Phobos, dans une station de recherche où il reste un prototype de Shield, "
        "l'EDF-Shield-NX01. Le professeur Kamarasov y travaillait sur l'intrication quantique "
        "macroscopique, avec Grok 294.5.\n"
        "\n"
        "Mais un drone espion avioïde s'était glissé dans la station. "
        "Le professeur Kamarasov a été tué avant d'avoir pu finaliser son invention.\n"
        "\n"
        "L'ancrage quantique n'a jamais été terminé. Si le NX01 est détruit, "
        "il ne reviendra pas. Et son pilote non plus.\n"
        "\n"
        "Il y a peu d'espoir. Mais à bord de ce prototype à peine capable de voler, "
        "je peux encore renverser le cours de l'histoire, moi, {name}, j'en suis maintenant certain."
    ),
}
_INTRO_FR["story_scene_dome_1"] = (
    'De rares survivants, échappés des colonies ravagées des lunes de Jupiter, affirment avoir aperçu la carcasse d’un EDF42-Shield dérivant en orbite haute autour de la géante gazeuse. Leurs récits concordent sur l’essentiel : la coque est éventrée de part en part, les propulseurs sont morts, et la dérive lente de l’épave dessine déjà une ellipse instable qui finira par la précipiter dans les bandes de nuages. Pourtant, le générateur de bouclier pourrait encore être récupérable — à condition que le cœur n’ait pas cédé sous le feu des Avioïdes.\n\n'
    'Il nous faut tenter de le ramener. Un bouclier encore fonctionnel, même endommagé, changerait le rapport de force sur tout le secteur. Les survivants parlent d’un clignotement intermittent dans la baie technique, d’une lueur froide qui s’allume encore par à-coups, comme si le système refusait de mourir. Personne n’a pu s’approcher assez près pour le confirmer. Les balises de détresse se sont tues depuis des semaines, et les dernières transmissions n’étaient plus que du bruit.\n\n'
    'Le problème, c’est qu’entre nous et l’épave s’étend tout un secteur sous contrôle avioïde. Leurs patrouilles quadrillent les corridors d’approche, leurs nids orbitaux surveillent les points de Lagrange, et la moindre signature de propulsion au-delà de la ligne de débris attire déjà une réponse. Atteindre la carcasse exigera une trajectoire précisément calculée, puis une extraction sous silence radio. Si le générateur tient, nous repartirons avec lui. S’il a cédé, nous n’aurons fait que confirmer la malédiction qui pèse sur la race humaine.'
)
_INTRO_FR["story_scene_sortie"] = (
    'Mars brûle de son éternel rouge ; là-bas somnole le NX01. Depuis la baie de Phobos, les capteurs relèvent des signatures minuscules, nombreuses, qui tournent au-dessus des cratères en se jouant des blocs d’astéroïdes. Ce sont des Avioïdes. Des oiseaux bleus, disent les rares survivants, à cause de la teinte de leur peau écailleuse, un bleu d’ardoise, un bleu de nuit, et de ces lueurs rouges qui couvent dans leurs yeux et dans leur poitrine.\n\n'
    'Personne ne sait ce qu’ils cherchent. Ils ne communiquent pas, ils n’exigent rien. Ils patrouillent, ils plongent, ils déchirent. Avec leurs ailes de cuir tendu, leurs serres incandescentes et leurs armes à plasma, ils ont mis en pièces plus de Shields que je n’ai d’heures de vol. Ce sont les éclaireurs de la horde, les plus rapides, les plus nombreux, et c’est toujours par eux que tout commence.\n\n'
    'Alors tant pis si le NX01 tient à peine en l’air. Il faut bien commencer par quelque part. Je vais sortir, les affronter un par un, et regarder de près ce qu’ils sont, car on ne bat que ce qu’on connaît bien. Si l’ancrage quantique fait ce que Kamarasov a promis, je reviendrai avec de quoi remplir le premier jeu de données. Sinon… eh bien, je n’aurai plus à m’en soucier.'
)
_INTRO_FR["story_scene_best2"] = (
    'Les bleus ne sont pas les seuls. Sur les relevés de la première sortie, d’autres signatures reviennent, plus denses, plus vives, loin de Mars, au-dessus d’une lune de Jupiter que la géante écrase de sa masse rayée. Ce sont encore des Avioïdes. Des oiseaux kaki, disent les rares survivants, à cause du vert militaire de leur peau, un vert de blindage, un vert de mousse sombre, et de ces braises orange qui brillent dans leurs yeux et au creux de leur poitrine.\n\n'
    'Là où les bleus plongent en ligne, les kakis arrivent en grappes et changent de cap sans prévenir. Leurs ailes de cuir battent plus vite, leurs serres claquent plus tôt, et leurs tirs de plasma se rapprochent. Ils se perdent dans la poussière des stations détruites. On ne les voit pas venir, ou alors trop tard.\n\n'
    'Cette fois, je ne sors pas pour regarder. Je sors pour apprendre à les battre. Ce qu’il y a derrière ces yeux orange, je le saurai en les voyant tomber, un par un, et chaque page ajoutée au Bestiaire rendra la suite moins périlleuse.'
)
_INTRO_FR["story_scene_best3"] = (
    'Les kakis ne sont pas les seuls à rôder. Plus loin, dans les anneaux de Saturne, les capteurs relèvent une signature que je ne reconnais pas. Plus massive, plus lente, et d’une froideur étrange. Ce ne sont plus des oiseaux. Les rares survivants parlent de gargouilles, à cause de leur carcasse de métal sombre, hérissée de plaques, et de ces yeux rouges qui s’allument sans un bruit, au fond d’un masque de pierre et d’acier.\n\n'
    'Les bleus plongent en ligne, les kakis arrivent en grappes. Les gargouilles, elles, ne forment rien. Elles dérivent seules entre les blocs de glace, patientes, puis fondent sur la première lueur de moteur qu’elles croisent. Leurs ailes encaissent les tirs comme un blindage, et si l’on tarde à les abattre, elles repoussent. Ce que le feu a arraché, la machine le reconstruit.\n\n'
    'Alors il faudra frapper vite, et frapper juste. Je sais ce que je risque, à tourner dans leurs anneaux avec un vaisseau qui tient à peine en l’air. Mais chaque gargouille tombée remplira une page de plus du Bestiaire, et m’apprendra comment venir à bout des suivantes. Si l’ancrage quantique fait ce que Kamarasov a promis, je reviendrai avec de quoi les faire plier. Sinon…'
)
_INTRO_FR["story_scene_best4"] = (
    'Les gargouilles ne sont pas les dernières. Bien au-delà de Saturne, là où le Soleil n’est plus qu’une étoile parmi d’autres, devant la pâle géante de glace d’Uranus, les relevés signalent des échos plus nombreux, plus vifs, presque invisibles. Ce sont encore des gargouilles, mais d’un violet si profond qu’il en paraît noir, un violet qui boit la lumière et ne laisse rien voir de leur carcasse. Seuls leurs yeux rouges les trahissent, deux braises fixes qui s’approchent bien plus vite qu’elles ne le devraient.\n\n'
    'Les survivants n’aiment pas en parler. Ceux qui l’ont fait disent qu’elles chassent en meute, qu’elles frappent avant même qu’on les ait vues, et que leurs ailes, quand elles se déploient, avalent jusqu’à la dernière lueur de la géante de glace. Certains jurent qu’elles repoussent plus vite que la gargouille. D’autres ne jurent plus de rien.\n\n'
    'Je ne sais pas si le NX01 est fait pour ça. Mais le Bestiaire n’aura de valeur que s’il est complet, et il ne le sera pas tant que cette page restera blanche. Alors j’y vais, avec la peur au ventre et le doigt sur la détente. Si l’ancrage quantique tient sa promesse, je reviendrai avec ce qu’il manque. Sinon, au moins, je n’aurai pas eu à le raconter.'
)
_INTRO_FR["story_scene_bestboss"] = (
    'Il reste une page du Bestiaire que je n’ai pas osé ouvrir. Tout au bout de l’espace connu, en orbite de Neptune, au-dessus de tempêtes bleues qui s’enroulent sur elles-mêmes depuis des millions d’années, les relevés ne signalent plus des meutes mais un seul écho, immense et immobile. Une soucoupe noire, craquelée comme une vieille cuirasse, ceinte de feux rouges qui pulsent lentement. Au sommet de son dôme, derrière une baie obscure, on devine une créature tentaculaire que personne n’a pu approcher sans y laisser la vie.\n\n'
    'C’est lui qui commande : le cerveau télépathique, le centre de l’intelligence collective des Avioïdes. Des gargouilles, vertes et sombres, tournent autour de la soucoupe sans jamais s’en éloigner. Terré en son cœur, derrière le blindage, il n’apparaît que lorsque la voie est dégagée, et il suffit alors d’un seul tir. Un seul. Encore faut-il l’atteindre. Nous en avons déjà abattu un. Un autre a pris sa place, plus coriace, puis un autre après lui.\n\n'
    'Je ne sais pas si l’on peut vraiment vaincre une chose pareille. Mais chaque fois qu’il tombera, je pourrai écrire une ligne de plus, et chaque ligne rendra la suivante moins incertaine. Alors j’y vais. Si l’ancrage quantique tient bon, je lui dirai ce que je pense de son élevage. Sinon, ce sera au prochain pilote de remplir la dernière page.'
)
_INTRO_FR["story_scene_paint_1"] = (
    'L’atelier clandestin du vieux Wallems, creusé dans le flanc de l’astéroïde 434-Hungaria, tourne encore. Malgré l’invasion. Malgré les patrouilles. On y voit toujours des coques posées sur tréteaux, des bidons ouverts, des masques penchés sur le métal…\n\n'
    'Je ne suis pas assez fou pour tenter de franchir les hordes d’Avioïdes qui quadrillent le secteur, rang après rang, rien que pour faire repeindre mon vaisseau. Non. Je ne le suis pas.\n\n'
    'Et pourtant la rumeur tient. Wallems prend encore les commandes, choisit ses teintes uniques à l’œil, et livre des coques magnifiques le tout avec en fond sonore des trompettes flamboyantes…\n'
    'Non, je n\'irai pas, ça serait du délire…'
)
_INTRO_FR["story_scene_bar"] = (
    'La porte du sas siffle en s’ouvrant, libérant une bouffée d’air recyclé qui sent le café et le métal rouillé. '
    'Je pose le pied sur le plancher grinçant du Dernier Rempart, le bar de la station Phobos.\n\n'
    'Autour de moi, c’est un chaos rouillé de néons roses et bleus qui clignotent sur des bornes d’arcade vintage. '
    'Des écrans cathodiques connectés à de vieilles consoles de jeux crachotent des scores en pixels verts, '
    'alors qu’une vieille chanson synthwave grésille dans les haut-parleurs.\n\n'
    'Je m’avance entre les tables. Personne ne me regarde. Ici, à la frontière de la ceinture d’astéroïdes, '
    'tout le monde a une histoire, et personne ne pose de questions.\n\n'
    'C’est l’endroit parfait pour oublier que l’humanité est menacée de disparition.\n\n'
    'Je m’approche d’une borne d’arcade du jeu *Phoenix* de Taito, dans le coin le plus sombre. '
    'Un frisson me parcourt la nuque. Sur l’écran noir, une ligne de texte clignote lentement :\n\n'
    'FREE PLAY. APPUYEZ SUR SELECT(5) POUR METTRE UN CRÉDIT PUIS SUR START(1) POUR JOUER.\n\n'
    'Je suis les consignes.\n\n'
    'Et la partie commence…'
)
for _k, _v in _INTRO_FR.items():
    _ADVENTURE_TEXTS[_k] = (_v, _v)

