for _k, (_fr, _en) in list(_ACT3_TEXTS.items()) + list(_VIP_TEXTS.items()):
    T[_k] = {_code: _en for _code in LANG_CODES}          # the English text until the French one is validated
    T[_k]["fr"] = _fr


def _build_adv_feats():
    for key, mission in _ACH_ADV_MISSIONS.items():
        T[key] = {c: _ACH_ADV_WIN[i].format(m=T[mission].get(c) or T[mission]["en"]) for i, c in enumerate(LANG_CODES)}


def _load_lang_files():
    """The other languages of the texts written above in French and English only (the Adventure, its scenes, the
    descriptions of the arcade game screen and of EXTRAS): one file per language, assets/lang/<code>.json, {key: text}
    (en.json holds the English of the scenes). A key a file does not have keeps the English text."""
    import json
    import os
    try:
        from settings import asset_path
    except Exception:
        return
    for code in LANG_CODES:
        path = asset_path("lang", code + ".json")
        if not os.path.isfile(path):
            continue
        try:
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            try:
                from errlog import log_exc
                log_exc("i18n._load_lang_files")
            except Exception:
                pass
            continue
        if not isinstance(data, dict):
            continue
        for key, text in data.items():
            if key in T and isinstance(text, str) and text:
                T[key][code] = text


_load_lang_files()
_build_adv_feats()

_lang = "fr"

def set_lang(code):
    global _lang
    if code in LANG_CODES:
        _lang = code
    else:
        _lang = "fr"

def get_lang():
    return _lang

def t(key):
    entry = T.get(key)
    if not entry:
        return key
    return entry.get(_lang) or entry.get("en") or key

def t_list(section):
    """Return list of lines for HELP scenario/howto/controls."""
    entry = HELP.get(section)
    if not entry:
        return []
    if isinstance(entry, dict) and _lang in entry and isinstance(entry[_lang], list):
        return entry[_lang]
    if isinstance(entry, dict) and "en" in entry and isinstance(entry["en"], list):
        return entry["en"]
    return []

def t_help(key):
    entry = HELP.get(key)
    if not entry:
        return key
    if isinstance(entry, dict):
        val = entry.get(_lang) or entry.get("en") or key
        if isinstance(val, list):
            return val
        return val
    return key
